func newDeliveryEngine(h *handlers.DeliveryHandler) *gin.Engine {
	r := gin.New()
	r.Use(gin.Recovery())
	h.RegisterRoutes(r)
	return r
}

func newDeliveryServer(port string, h *handlers.DeliveryHandler) *http.Server {
	if port == "" {
		return nil
	}
	return &http.Server{
		Addr:    ":" + port,
		Handler: newDeliveryEngine(h),
	}
}

