func (s *Server) StartDelivery() error {
	if s.deliveryServer == nil {
		return nil
	}
	s.logger.Info("Starting Core Manager delivery listener (customer routes only)", zap.String("address", s.deliveryServer.Addr))
	return s.deliveryServer.ListenAndServe()
}

func (s *Server) Shutdown(ctx context.Context) error {
	s.kafkaProducer.Close()
	if s.deliveryServer != nil {
		if err := s.deliveryServer.Shutdown(ctx); err != nil {
			s.logger.Error("Delivery listener shutdown failed", zap.Error(err))
		}
	}
	return s.httpServer.Shutdown(ctx)
}

type ServerConfig struct {
	Port string `mapstructure:"port"`

	// DeliveryPort, when set, starts a SECOND HTTP listener carrying only the
	// customer-facing delivery routes (/c/, later /d/). Used by core-manager.
	// IT IS OPT-IN AND ITS DEFAULT IS OFF, deliberately: the authority it grants
	// is a listener that accepts public traffic ... Empty means no second
	// listener AND the delivery routes are mounted nowhere at all — the door is
	// shut, not quietly re-opened on the admin port.
	DeliveryPort string `mapstructure:"delivery_port"`
}

